<div x-show="intakeModalOpen" x-cloak class="fixed inset-0 z-[60] flex items-center justify-center bg-black/40 p-4" role="dialog" aria-modal="true"><div  class="flex max-h-[90vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl bg-white shadow-xl"><header class="flex items-center justify-between border-b border-gray-100 p-6"><div><p class="text-[10px] font-semibold uppercase tracking-[0.16em] text-gray-500">APPLICATIONS PIPELINE</p><h2 class="mt-1 text-lg font-bold text-gray-900">New ID Application</h2></div><button type="button" @click="intakeModalOpen = false" aria-label="Close new application" class="text-gray-500 hover:text-gray-900"><svg class="h-6 w-6" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="flex items-center border-b border-gray-100 px-6 py-4"><template x-for="(label, step) in {1: 'Personal Info', 2: 'Address & Applicant', 3: 'Document Checklist'}" :key="step"><div class="flex flex-1 items-start"><div class="flex flex-1 flex-col items-center gap-1"><div class="flex h-8 w-8 items-center justify-center rounded-full border-2 text-sm font-medium" :class="intakeStep >= step ? 'border-blue-600 bg-blue-600 text-white' : 'border-gray-200 bg-white text-gray-400'"><svg x-show="intakeStep > step" class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" stroke-linejoin="round" d="m5 12 4 4L19 6"/></svg><span x-show="intakeStep <= step" x-text="step"></span></div><span class="mt-1 whitespace-nowrap text-[10px] font-semibold" :class="intakeStep === step ? 'text-blue-600' : 'text-gray-500'" x-text="label"></span></div><div x-show="step < 3" class="mx-2 mt-4 h-px flex-1 bg-gray-200"></div></div></template></div><section x-show="intakeStep === 1" class="overflow-y-auto p-6"><div class="grid grid-cols-1 gap-4 sm:grid-cols-2"><label class="sm:col-span-2"><span class="field-label">LAST NAME *</span><input x-model="intakeForm.lastName" type="text" placeholder="e.g. Santos" class="field-input"></label><label><span class="field-label">FIRST NAME *</span><input x-model="intakeForm.firstName" type="text" placeholder="e.g. Maria Lourdes" class="field-input"></label><label><span class="field-label">MIDDLE NAME</span><input x-model="intakeForm.middleName" type="text" placeholder="e.g. Cruz" class="field-input"></label><label><span class="field-label">DATE OF BIRTH *</span><input x-model="intakeForm.dob" @input="calculateAge()" @change="calculateAge()" type="date" class="field-input"></label><label><span class="field-label">AGE</span><input x-model="intakeForm.age" type="text" readonly placeholder="Auto-computed" class="field-input cursor-not-allowed bg-gray-50 text-gray-700 font-medium"></label><label class="sm:col-span-2"><span class="field-label">SEX *</span><select x-model="intakeForm.sex" class="field-input"><option value="">— Select sex —</option><option>Female</option><option>Male</option></select></label></div></section><section x-show="intakeStep === 2" x-cloak class="overflow-y-auto p-6"><div class="grid grid-cols-1 gap-4 sm:grid-cols-2"><label><span class="field-label">PROVINCE</span><input type="text" value="Bulacan" readonly disabled class="field-input cursor-not-allowed border-gray-200 bg-gray-50 text-gray-500"></label><label><span class="field-label">MUNICIPALITY / CITY</span><input type="text" value="Santa Maria" readonly disabled class="field-input cursor-not-allowed border-gray-200 bg-gray-50 text-gray-500"></label><label><span class="field-label">BARANGAY *</span><select x-model="intakeForm.barangay" class="field-input"><option value="">All Barangays</option>@foreach (['Bagbaguin','Balasing','Buenavista','Bulac','Camangyanan','Catmon','Caypombo','Caysio','Guyong','Lalakhan','Mag-asawang Sapa','Mahabang Parang','Manggahan','Parada','Poblacion','Pulong Buhangin','San Gabriel','San Jose Patag','San Vicente','Santa Clara','Santa Cruz','Silangan','Santo Tomas','Tumana'] as $barangay)<option>{{ $barangay }}</option>@endforeach</select></label><label><span class="field-label">HOUSE NO. / STREET / SUBDIVISION</span><input x-model="intakeForm.street" type="text" placeholder="e.g. 12 Sampaguita St." class="field-input"></label><label class="sm:col-span-2"><span class="field-label">SENIOR'S MOBILE NUMBER</span><div class="flex"><span class="flex items-center rounded-l-xl border border-r-0 border-gray-200 bg-gray-50 px-3 text-sm text-gray-500">+63</span><input x-model="intakeForm.mobile" type="tel" placeholder="9XX XXX XXXX" class="field-input rounded-l-none"></div></label></div><div class="mt-5"><span class="field-label">APPLICANT TYPE</span><div class="grid grid-cols-2 overflow-hidden rounded-xl border border-gray-200 bg-white"><button type="button" @click="intakeForm.applicantType = 'Walk-in (Self)'" :style="intakeForm.applicantType === 'Walk-in (Self)' ? 'background-color: #2563eb; color: #ffffff;' : 'background-color: #ffffff; color: #374151;'" class="flex cursor-pointer items-center justify-center gap-2 px-4 py-3 text-sm transition-colors"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="8" r="3"/><path stroke-linecap="round" d="M5 20a7 7 0 0 1 14 0"/></svg>Walk-in (Self)</button><button type="button" @click="intakeForm.applicantType = 'Proxy / Representative'" :style="intakeForm.applicantType === 'Proxy / Representative' ? 'background-color: #2563eb; color: #ffffff;' : 'background-color: #ffffff; color: #374151;'" class="flex cursor-pointer items-center justify-center gap-2 border-l border-gray-200 px-4 py-3 text-sm transition-colors"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="9" cy="8" r="3"/><path stroke-linecap="round" d="M3 20a6 6 0 0 1 12 0M16 4.5a3 3 0 0 1 0 7M17 14a5 5 0 0 1 5 6"/></svg>Proxy / Representative</button></div><div x-show="intakeForm.applicantType === 'Proxy / Representative'" x-transition class="mt-4 space-y-4 rounded-2xl border border-amber-200 bg-amber-50/70 p-5"><div class="flex items-center gap-2"><svg class="h-5 w-5 text-amber-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" d="M12 9v4m0 3h.01M10.3 4.5 2.7 18a2 2 0 0 0 1.7 3h15.2a2 2 0 0 0 1.7-3L13.7 4.5a2 2 0 0 0-3.4 0Z"/></svg><span class="text-sm font-bold text-amber-800">Proxy Application — Additional Requirements</span></div><p class="text-xs leading-relaxed text-amber-700">A representative is applying on the senior's behalf. The guardian must present all additional documents below.</p><div class="grid grid-cols-1 gap-4 sm:grid-cols-2"><label><span class="field-label">GUARDIAN / REPRESENTATIVE NAME *</span><input x-model="intakeForm.proxyName" type="text" placeholder="Full name" class="field-input bg-white"></label><label><span class="field-label">RELATIONSHIP TO SENIOR *</span><input x-model="intakeForm.proxyRelationship" type="text" placeholder="e.g. Son, Daughter" class="field-input bg-white"></label><label><span class="field-label">GUARDIAN CONTACT NUMBER *</span><input x-model="intakeForm.proxyMobile" type="tel" placeholder="09XX XXX XXXX" class="field-input bg-white"></label></div><label class="flex items-start gap-3 rounded-xl border border-gray-200 bg-white p-4"><input type="checkbox" x-model="intakeForm.authLetterChecked" class="mt-0.5 h-4 w-4 cursor-pointer rounded border-gray-300 text-blue-600 focus:ring-blue-500"><span><span class="text-sm font-bold text-gray-800">Authorization Letter presented</span><span class="mt-0.5 block text-xs text-gray-500">Signed by the senior citizen, confirming the representative's authority.</span></span></label></div></div></section><section x-show="intakeStep === 3" x-cloak class="overflow-y-auto p-6"><div class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-amber-800"><p class="font-bold">Staff verification required</p><p class="mt-1 text-sm">Physically inspect the Government ID and upload the applicant's digital 1x1 photo.</p></div><label class="mt-5 flex cursor-pointer items-start gap-3 rounded-2xl border border-gray-200 bg-white p-4"><input type="checkbox" x-model="intakeForm.govIdChecked" class="mt-0.5 h-4 w-4 cursor-pointer rounded border-gray-300 text-blue-600 focus:ring-blue-500"><span><span class="text-sm font-bold text-gray-800">Valid Government-Issued ID</span><span class="mt-0.5 block text-xs text-gray-500">Must show the applicant's current address in Santa Maria, Bulacan.</span></span></label><div class="mt-5"><p class="field-label">APPLICANT 1X1 ID PHOTO</p><div class="rounded-2xl border-2 border-dashed border-gray-200 bg-gray-50/40 p-6 text-center"><input type="file" x-ref="photoInput" accept="image/jpeg,image/png" class="hidden" @change="handlePhotoUpload($event)"><div x-show="!intakeForm.photoPreview" class="flex flex-col items-center justify-center space-y-2.5"><button type="button" @click.prevent="$refs.photoInput.click()" style="background-color: #2563eb; color: #ffffff;" class="inline-flex cursor-pointer items-center gap-2 rounded-xl px-5 py-2.5 text-sm font-semibold shadow-xs hover:opacity-95"><svg class="h-4 w-4" fill="none" stroke="currentColor" stroke-width="1.75" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M6.827 6.175A2.31 2.31 0 0 1 5.186 7.23c-.38.054-.757.112-1.134.175C2.999 7.58 2.25 8.507 2.25 9.574V18a2.25 2.25 0 0 0 2.25 2.25h15A2.25 2.25 0 0 0 21.75 18V9.574c0-1.067-.75-1.994-1.802-2.169a47.865 47.865 0 0 0-1.134-.175 2.31 2.31 0 0 1-1.64-1.055l-.822-1.316a2.192 2.192 0 0 0-1.736-1.039 48.774 48.774 0 0 0-5.232 0 2.192 2.192 0 0 0-1.736 1.039l-.821 1.316Z"/><path stroke-linecap="round" stroke-linejoin="round" d="M16.5 12.75a4.5 4.5 0 1 1-9 0 4.5 4.5 0 0 1 9 0Z"/></svg><span>Browse / Upload File</span></button><p class="text-xs text-gray-500">Upload a clear, recent 1×1 photo with a plain background (JPG or PNG)</p></div><div x-show="intakeForm.photoPreview" class="flex flex-col items-center space-y-2"><img :src="intakeForm.photoPreview" class="h-24 w-24 rounded-xl border border-gray-300 object-cover shadow-xs"><p class="text-xs font-medium text-gray-700" x-text="intakeForm.photoName"></p><button type="button" @click.prevent="$refs.photoInput.click()" class="cursor-pointer text-xs font-semibold text-blue-600 hover:underline">Change Photo</button></div></div></div></section><footer class="flex items-center justify-between border-t border-gray-100 bg-gray-50 p-4"><button type="button" @click="intakeStep === 1 ? intakeModalOpen = false : intakeStep--" class="rounded-xl border border-gray-200 bg-white px-5 py-3 font-medium text-gray-700"><span x-text="intakeStep === 1 ? 'Cancel' : '← Back'"></span></button><span class="text-sm text-gray-500" x-text="`Step ${intakeStep} of 3`"></span><button type="button" @click="intakeStep === 1 ? nextIntakeStep() : intakeStep === 2 ? nextIntakeStep() : submitIntakeApplication()" :disabled="(intakeStep === 1 && !isStep1Valid()) || (intakeStep === 2 && !isStep2Valid()) || (intakeStep === 3 && !isStep3Valid())" :style="(intakeStep === 1 ? isStep1Valid() : intakeStep === 2 ? isStep2Valid() : isStep3Valid()) ? 'background-color: #2563eb; color: #ffffff; cursor: pointer;' : 'background-color: #93c5fd; color: #ffffff; cursor: not-allowed;'" class="rounded-xl px-6 py-2.5 text-sm font-semibold shadow-xs transition-all"><span x-text="intakeStep === 3 ? 'Submit Application' : 'Continue →'"></span></button></footer></div></div>
